const app=document.querySelector('#app');
const state={tab:'check',category:'Водка',volume:'0,7',product:'Сябры. Чистая',rules:[],sourceName:'информ.редизайн Сябры Чистая 0,2 0,5 0,7.docx',fileName:'sjabry_chistaja_0,7L_54x103.pdf',image:null,pdf:null,page:1,pages:1,label:null,width:0,height:0,full:false,zoom:100,actual:'',origin:'',review:{},margin:false,selected:'r0',filter:'all',busy:false,progress:0,busyMessage:'',edited:false,error:'',geometryConfirmed:false,words:[],matches:{},hasContour:false,pageMm:null,analysisNote:''};
let worker=null,workerLanguage='',ocrGeneration=0;
