const comparisonNames={found:'Текст совпадает с требованиями',all_words:'Все слова найдены; порядок не подтверждён',partial:'Есть отличия в чтении OCR',uncertain:'OCR неуверенно прочитал символы',unreadable:'OCR не прочитал слова',manual:'Проверяется вручную',na:'Не применяется'};
